import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  /** Absent for users who only ever signed in with Google. */
  passwordHash?: string;
};

// Demo password for the two seeded accounts below is "password123".
const SEED_PASSWORD_HASH =
  "$2b$10$C6wAgGDFEAssmuc1KADAvueBNH5TGDzebifTDJ5jw.8gIMBLY8YM2";

const users: User[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    passwordHash: SEED_PASSWORD_HASH,
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    passwordHash: SEED_PASSWORD_HASH,
  },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

/**
 * Checks an email/password pair against the store. Used by the Credentials
 * provider in src/lib/auth.ts.
 */
export async function verifyCredentials(
  email: string,
  password: string
): Promise<User | null> {
  const user = await getUserByEmail(email);
  if (!user?.passwordHash) return null;
  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? user : null;
}

/**
 * Creates a new email/password account. Used by the sign-up form action.
 * Throws if the email is already registered.
 */
export async function createUserWithPassword(
  email: string,
  name: string,
  password: string
): Promise<User> {
  const normalizedEmail = email.trim().toLowerCase();
  if (await getUserByEmail(normalizedEmail)) {
    throw new Error("A user with that email already exists.");
  }

  const passwordHash = await bcrypt.hash(password, 10);
  const user: User = {
    id: String(nextId++),
    email: normalizedEmail,
    name: name.trim() || normalizedEmail,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return user;
}

/**
 * Finds or provisions a user for an OAuth (Google) sign-in. Used by the
 * signIn callback in src/lib/auth.ts.
 */
export async function findOrCreateOAuthUser(
  email: string,
  name: string
): Promise<User> {
  const existing = await getUserByEmail(email);
  if (existing) return existing;

  const user: User = {
    id: String(nextId++),
    email: email.trim().toLowerCase(),
    name: name.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
    // no passwordHash — this account can only sign in via Google
  };
  users.push(user);
  return user;
}

/** Reads the signed-in user (if any) from the current auth session. */
export async function getCurrentUser(): Promise<User | undefined> {
  // Imported lazily to avoid a module-init cycle with src/lib/auth.ts, which
  // itself imports from this file to authenticate against the user store.
  const { auth } = await import("@/lib/auth");
  const session = await auth();
  if (!session?.user?.email) return undefined;
  return getUserByEmail(session.user.email);
}

