import type { NextAuthConfig } from "next-auth";

/**
 * The subset of the NextAuth config that's safe to run in the Edge
 * middleware runtime (no Node-only dependencies like bcrypt or the
 * Credentials provider's `authorize` implementation). The full config,
 * including providers, lives in src/lib/auth.ts.
 */
export const authConfig = {
  pages: {
    signIn: "/login",
  },
  callbacks: {
    authorized({ auth, request: { nextUrl } }) {
      const isLoggedIn = !!auth?.user;
      const isOnDashboard = nextUrl.pathname.startsWith("/dashboard");

      if (isOnDashboard) {
        return isLoggedIn;
      }

      return true;
    },
  },
  providers: [], // configured in src/lib/auth.ts
} satisfies NextAuthConfig;

